import type { z } from "zod";
import type {
	productSchema,
	productVariantSchema,
	productsQuerySchema,
	shippingAddressSchema,
	checkoutSchema,
	orderStatusSchema,
	cartItemSchema,
} from "./schemas";

/** CMS product exposed by the storefront. */
export type Product = z.output<typeof productSchema> & {
	id: string;
	slug: string;
	createdAt: string;
	updatedAt: string;
};
export type ProductVariant = z.output<typeof productVariantSchema>;
export type ProductsFilters = z.input<typeof productsQuerySchema>;
export type ProductsPage = {
	items: Product[];
	total: number;
	limit: number;
	offset: number;
	categories: string[];
	collections: string[];
};
export type CartItem = z.output<typeof cartItemSchema>;
export type ShippingAddress = z.output<typeof shippingAddressSchema>;
export type CheckoutInput = z.input<typeof checkoutSchema>;
export type OrderStatus = z.output<typeof orderStatusSchema>;
export type OrderLineItem = {
	productId: string;
	variantId?: string;
	name: string;
	variantName?: string;
	quantity: number;
	price: number;
	image?: string;
};
/** Safe order representation; access tokens and idempotency keys are never listed. */
export type Order = {
	id: string;
	email: string;
	customerId?: string | null;
	status: OrderStatus;
	lineItems: OrderLineItem[];
	subtotal: number;
	discount: number;
	shipping: number;
	total: number;
	currency: string;
	shippingAddress: ShippingAddress;
	paymentProvider: string;
	paymentRef?: string | null;
	paymentStatus: "pending" | "paid" | "failed" | "refunded";
	createdAt: string;
	updatedAt: string;
};
export type OrdersPage = { items: Order[]; total: number };
export type OrderRecord = Omit<
	Order,
	"lineItems" | "shippingAddress" | "createdAt" | "updatedAt"
> & {
	lineItems: string;
	shippingAddress: string;
	createdAt: Date;
	updatedAt: Date;
	accessToken: string;
	idempotencyKey: string;
	checkoutFingerprint: string;
	paymentData: string;
	discountCodeId?: string | null;
	inventoryReleased: boolean;
	paidHookDelivered: boolean;
};
export type DiscountCode = {
	id: string;
	code: string;
	type: "percent" | "fixed";
	value: number;
	maxUses?: number | null;
	uses: number;
	expiresAt?: Date | null;
};
export type CheckoutResult = {
	orderId: string;
	accessToken: string;
	payment: { redirectUrl?: string; clientSecret?: string };
};
/** Serialized products and orders already carry ISO date strings. */
export type SerializedProduct = Product;
export type ProductListParams = ProductsFilters;
export type ProductListResult = ProductsPage;
export type SerializedOrder = Order;
export type CartLineInput = CartItem;
export type DiscountResult = {
	code: string;
	discount: number;
	subtotal: number;
	total: number;
	currency: string;
};

/** Authoritative remaining stock after initialization from the CMS product. */
export type InventoryRecord = {
	id: string;
	key: string;
	productId: string;
	variantId?: string | null;
	stock: number;
};

import { z } from "zod";
import type { ContentTypeConfig } from "@btst/plugin-cms/api";

const money = z.number().int().min(0).max(100_000_000);
export const productVariantSchema = z.object({
	id: z.string().min(1).max(100),
	name: z.string().trim().min(1).max(200),
	options: z.record(z.string().max(100), z.string().max(100)).default({}),
	price: money.optional(),
	stock: z.number().int().min(0).max(1_000_000).default(0).meta({
		title: "Initial stock",
		description:
			"Used only until commerce inventory is initialized. Restock through updateInventory with expectedStock.",
	}),
	sku: z.string().max(100).optional(),
});
/** Product data authored in CMS; all amounts are integer minor units. */
export const productSchema = z.object({
	name: z.string().trim().min(1).max(200),
	description: z
		.string()
		.max(100_000)
		.default("")
		.meta({ fieldType: "markdown" }),
	price: money,
	currency: z
		.string()
		.regex(/^[A-Z]{3}$/)
		.default("USD"),
	stock: z.number().int().min(0).max(1_000_000).default(0).meta({
		title: "Initial stock",
		description:
			"Used only until commerce inventory is initialized. Restock through updateInventory with expectedStock.",
	}),
	images: z
		.array(z.string().min(1).max(2048))
		.max(20)
		.default([])
		.meta({ fieldType: "ecommerce-images" }),
	category: z.string().trim().max(100).optional(),
	collections: z.array(z.string().trim().min(1).max(100)).max(30).default([]),
	tags: z.array(z.string().trim().min(1).max(100)).max(30).default([]),
	status: z
		.enum(["draft", "published", "archived"])
		.default("draft")
		.meta({ fieldType: "select" }),
	variants: z
		.array(productVariantSchema)
		.max(100)
		.default([])
		.refine(
			(variants) =>
				new Set(variants.map((variant) => variant.id)).size === variants.length,
			"Variant IDs must be unique",
		),
});
export const PRODUCT_TYPE_SLUG = "ecommerce-product" as const;
/** Register this alongside the Ecommerce backend plugin in CMS contentTypes. */
export const PRODUCT_CONTENT_TYPE: ContentTypeConfig = {
	name: "Product",
	slug: PRODUCT_TYPE_SLUG,
	description: "Storefront products and inventory",
	schema: productSchema,
};
const optionalText = z.string().trim().max(200).optional();
export const productsQuerySchema = z.object({
	category: optionalText,
	collection: optionalText,
	search: optionalText,
	minPrice: z.coerce.number().int().min(0).optional(),
	maxPrice: z.coerce.number().int().min(0).optional(),
	inStock: z.preprocess(
		(v) => (v === "true" ? true : v === "false" ? false : v),
		z.boolean().optional(),
	),
	limit: z.coerce.number().int().min(1).max(100).default(24),
	offset: z.coerce.number().int().min(0).default(0),
});
export const cartItemSchema = z.object({
	productId: z.string().min(1).max(200),
	variantId: z.string().min(1).max(100).optional(),
	quantity: z.number().int().min(1).max(100),
});
export const shippingAddressSchema = z.object({
	name: z.string().trim().min(1).max(200),
	line1: z.string().trim().min(1).max(200),
	line2: z.string().trim().max(200).optional(),
	city: z.string().trim().min(1).max(100),
	region: z.string().trim().max(100).optional(),
	postalCode: z.string().trim().min(1).max(30),
	country: z.string().regex(/^[A-Z]{2}$/),
});
export const checkoutSchema = z.object({
	items: z.array(cartItemSchema).min(1).max(50),
	email: z.email().max(254),
	shippingAddress: shippingAddressSchema,
	discountCode: z.string().trim().min(1).max(100).optional(),
	idempotencyKey: z.uuid(),
});
export const orderStatusSchema = z.enum([
	"pending",
	"paid",
	"fulfilling",
	"fulfilled",
	"cancelled",
]);
export const createDiscountSchema = z
	.object({
		code: z
			.string()
			.trim()
			.min(1)
			.max(100)
			.transform((v) => v.toUpperCase()),
		type: z.enum(["percent", "fixed"]),
		value: money,
		maxUses: z.number().int().positive().optional(),
		expiresAt: z.iso.datetime().optional(),
	})
	.refine(
		(v) => v.type !== "percent" || v.value <= 100,
		"Percent discount must be at most 100",
	);
export const ordersQuerySchema = z.object({
	status: orderStatusSchema.optional(),
	limit: z.coerce.number().int().min(1).max(100).default(25),
	offset: z.coerce.number().int().min(0).default(0),
});

/** Restocking requires the last observed available count to prevent lost updates. */
export const updateInventorySchema = z.object({
	productId: z.string().min(1).max(200),
	variantId: z.string().min(1).max(100).optional(),
	stock: z.number().int().min(0).max(1_000_000),
	expectedStock: z.number().int().min(0),
});

import { definePermissions, permission } from "@btst/stack/authorization";
import { z } from "zod";
const id = z.object({ id: z.string().optional() });
/** Public buying, authenticated customer history, and private administration are separate capabilities. */
export const ecommercePermissions = definePermissions("ecommerce", {
	product: {
		read: permission(z.object({ slug: z.string().optional() })),
		manage: permission(id),
	},
	checkout: {
		create: permission(z.object({})),
		webhook: permission(z.object({})),
	},
	discount: {
		validate: permission(z.object({})),
		manage: permission(z.object({})),
	},
	order: {
		read: permission(id),
		update: permission(id),
		own: permission(z.object({ customerId: z.string() })),
		confirmation: permission(z.object({ id: z.string() })),
	},
});

import type { Order } from "../types";

export interface CheckoutAttempt {
	fingerprint?: string;
	key?: string;
	orderId?: string;
	uncertain?: boolean;
}

export function isTerminalOrder(
	order: Pick<Order, "status" | "paymentStatus">,
) {
	return order.paymentStatus !== "pending" || order.status === "cancelled";
}

/** Reuse ambiguous/pending attempts; only a verified terminal order permits a new payment. */
export async function reusableCheckoutAttempt(
	attempt: CheckoutAttempt | undefined,
	fingerprint: string,
	verifyOrder: (id: string) => Promise<Pick<Order, "status" | "paymentStatus">>,
): Promise<CheckoutAttempt | undefined> {
	if (!attempt || typeof attempt.key !== "string") return undefined;
	if (attempt.orderId && isTerminalOrder(await verifyOrder(attempt.orderId)))
		return undefined;
	if (attempt.fingerprint !== fingerprint) {
		throw new Error(
			"Your previous payment may still be active. Complete it, cancel it with the payment provider, or contact the shop to reconcile it before changing checkout details.",
		);
	}
	return attempt.orderId ? attempt : { ...attempt, uncertain: true };
}

/** A later rejection cannot disprove an earlier request with an unknown outcome. */
export function canDiscardCheckoutAttempt(
	attempt: CheckoutAttempt | undefined,
	submittedKey: string,
	code: unknown,
) {
	return (
		code === "CHECKOUT_NOT_CREATED" &&
		attempt?.key === submittedKey &&
		!attempt.orderId &&
		!attempt.uncertain
	);
}

"use client";
import { useState } from "react";
import {
	Sheet,
	SheetContent,
	SheetDescription,
	SheetHeader,
	SheetTitle,
	SheetTrigger,
} from "@/components/ui/sheet";
import { Button } from "@/components/ui/button";
import { usePluginSiteNavigation } from "@btst/stack/context";
import { ECOMMERCE_PLUGIN_ID } from "../constants";
import { useCart } from "@btst/plugin-ecommerce/client/hooks";
import { CartItems } from "./cart-items";

export function CartDrawer() {
	const [open, setOpen] = useState(false);
	const cart = useCart();
	const { Link, resolve } = usePluginSiteNavigation(ECOMMERCE_PLUGIN_ID);
	return (
		<Sheet open={open} onOpenChange={setOpen}>
			<SheetTrigger asChild>
				<Button variant="outline" size="sm">
					Open cart
				</Button>
			</SheetTrigger>
			<SheetContent className="flex flex-col">
				<SheetHeader>
					<SheetTitle>Your cart ({cart.count})</SheetTitle>
					<SheetDescription>
						Review quantities before checkout. Prices and availability are
						confirmed at checkout.
					</SheetDescription>
				</SheetHeader>
				<div className="flex-1 overflow-auto px-4">
					{cart.items.length ? (
						<CartItems />
					) : (
						<p className="py-8 text-muted-foreground">Your cart is empty.</p>
					)}
				</div>
				{cart.items.length ? (
					<div className="border-t p-4">
						<Button asChild className="w-full">
							<Link
								href={resolve("/shop/cart").href}
								onClick={() => setOpen(false)}
							>
								Review cart
							</Link>
						</Button>
					</div>
				) : null}
			</SheetContent>
		</Sheet>
	);
}

"use client";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { useCart } from "@btst/plugin-ecommerce/client/hooks";
import { ProductImage } from "./product-image";
import { formatMoney } from "./storefront";

export function CartItems() {
	const cart = useCart();
	return (
		<ul className="divide-y">
			{cart.items.map((item) => (
				<li
					key={`${item.productId}:${item.variantId ?? ""}`}
					className="flex gap-4 py-5"
				>
					<div className="h-20 w-20 shrink-0 overflow-hidden rounded-md">
						<ProductImage image={item.image} alt={item.name} />
					</div>
					<div className="min-w-0 flex-1">
						<p className="font-medium">{item.name}</p>
						{item.variantName ? (
							<p className="text-sm text-muted-foreground">
								{item.variantName}
							</p>
						) : null}
						<p className="mt-1 text-sm">
							{formatMoney(item.price, item.currency)}
						</p>
						<div className="mt-3 flex flex-wrap items-center gap-3">
							<label className="flex items-center gap-2 text-sm">
								Quantity
								<span className="sr-only">
									{" "}
									for {item.name}
									{item.variantName ? ` ${item.variantName}` : ""}
								</span>
								<Input
									className="w-20"
									type="number"
									min={1}
									max={99}
									value={item.quantity}
									onChange={(event) =>
										cart.updateQuantity(
											item.productId,
											item.variantId,
											Number(event.target.value),
										)
									}
								/>
							</label>
							<Button
								variant="ghost"
								size="sm"
								onClick={() => cart.removeItem(item.productId, item.variantId)}
								aria-label={`Remove ${item.name}${item.variantName ? ` ${item.variantName}` : ""}`}
							>
								Remove
							</Button>
						</div>
					</div>
					<p className="text-sm font-medium tabular-nums">
						{formatMoney(item.price * item.quantity, item.currency)}
					</p>
				</li>
			))}
		</ul>
	);
}

"use client";
import { usePluginSiteNavigation } from "@btst/stack/context";
import { Button } from "@/components/ui/button";
import { ECOMMERCE_PLUGIN_ID } from "../../constants";
import { useCart } from "@btst/plugin-ecommerce/client/hooks";
import { CartItems } from "../cart-items";
import { EmptyCart, Storefront, formatMoney } from "../storefront";

export function CartPage() {
	const cart = useCart();
	const { Link, resolve } = usePluginSiteNavigation(ECOMMERCE_PLUGIN_ID);
	return (
		<Storefront>
			{!cart.isHydrated ? (
				<p role="status">Loading cart…</p>
			) : cart.items.length ? (
				<>
					<h1 className="mb-8 text-3xl font-semibold tracking-tight">
						Your cart
					</h1>
					<div className="grid items-start gap-10 md:grid-cols-[minmax(0,1fr)_20rem]">
						<CartItems />
						<aside className="rounded-lg bg-muted/40 p-6">
							<h2 className="text-lg font-medium">Order summary</h2>
							<p className="mt-6 flex justify-between gap-4">
								<span>Subtotal</span>
								<strong className="tabular-nums">
									{formatMoney(cart.subtotal, cart.items[0]?.currency ?? "USD")}
								</strong>
							</p>
							<p className="mt-3 text-sm leading-6 text-muted-foreground">
								Discounts, shipping and final availability are confirmed at
								checkout.
							</p>
							{!cart.storageAvailable ? (
								<p role="status" className="mt-3 text-sm">
									Your browser could not save this cart. Keep this tab open
									until checkout.
								</p>
							) : null}
							<Button asChild className="mt-6 h-11 w-full">
								<Link href={resolve("/shop/checkout").href}>Checkout</Link>
							</Button>
						</aside>
					</div>
				</>
			) : (
				<EmptyCart />
			)}
		</Storefront>
	);
}

"use client";
import { useEffect, useRef, useState } from "react";
import {
	usePluginOverrides,
	usePluginSiteNavigation,
} from "@btst/stack/context";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { z } from "zod";
import { checkoutSchema, shippingAddressSchema } from "../../../schemas";
import type { CheckoutResult, Order, ShippingAddress } from "../../../types";
import { useCart, type CartItem } from "@btst/plugin-ecommerce/client/hooks";
import type { DiscountResult } from "@btst/plugin-ecommerce/query-keys";
import { useEcommerceEndpoint } from "@btst/plugin-ecommerce/client/hooks";
import {
	useCheckout,
	useValidateDiscount,
	useVerifyCheckoutOrder,
} from "@btst/plugin-ecommerce/client/hooks";
import { ECOMMERCE_PLUGIN_ID } from "../../constants";
import type { EcommercePluginOverrides } from "../../overrides";
import {
	reusableCheckoutAttempt,
	isTerminalOrder,
	canDiscardCheckoutAttempt,
	type CheckoutAttempt,
} from "../../checkout-attempt";
import { orderTokenKey } from "../../order-access";
import {
	EmptyCart,
	ErrorMessage,
	Storefront,
	formatMoney,
} from "../storefront";

const addressFields = [
	["name", "Full name", "name"],
	["line1", "Address", "address-line1"],
	["line2", "Apartment, suite, etc. (optional)", "address-line2"],
	["city", "City", "address-level2"],
	["region", "State / region (optional)", "address-level1"],
	["postalCode", "Postal code", "postal-code"],
	["country", "Country code", "country"],
] as const;

function paymentRedirectUrl(payment: CheckoutResult["payment"]) {
	if (!payment.redirectUrl) return undefined;
	const target = new URL(payment.redirectUrl, window.location.href);
	if (!["https:", "http:"].includes(target.protocol))
		throw new Error("The payment provider returned an invalid redirect URL.");
	return target.href;
}

export function CheckoutPage() {
	const cart = useCart();
	const checkout = useCheckout();
	const verifyOrder = useVerifyCheckoutOrder();
	const submitting = useRef(false);
	const applyingDiscount = useRef(false);
	const [isPreparing, setIsPreparing] = useState(false);
	const [isResuming, setIsResuming] = useState(true);
	const [resumeFailed, setResumeFailed] = useState(false);
	const [resumeVersion, setResumeVersion] = useState(0);
	const endpoint = useEcommerceEndpoint();
	const discount = useValidateDiscount();
	const [step, setStep] = useState<"shipping" | "payment">("shipping");
	const [email, setEmail] = useState("");
	const [address, setAddress] = useState<ShippingAddress>({
		name: "",
		line1: "",
		line2: "",
		city: "",
		region: "",
		postalCode: "",
		country: "US",
	});
	const [code, setCode] = useState("");
	const [appliedCode, setAppliedCode] = useState("");
	const [validationError, setValidationError] = useState<Error>();
	const [payment, setPayment] = useState<CheckoutResult>();
	const [paymentInitialized, setPaymentInitialized] = useState(false);
	const [submittedCart, setSubmittedCart] = useState<{
		items: CartItem[];
		discount?: DiscountResult;
		fingerprint: string;
	}>();
	const discountLocked =
		paymentInitialized ||
		isPreparing ||
		checkout.isPending ||
		discount.isPending;
	const key = useRef<string | undefined>(undefined);
	const { PaymentForm } = usePluginOverrides<
		EcommercePluginOverrides,
		Partial<EcommercePluginOverrides>
	>(ECOMMERCE_PLUGIN_ID, {});
	const { navigate } = usePluginSiteNavigation(ECOMMERCE_PLUGIN_ID);
	const items = cart.items.map(({ productId, variantId, quantity }) => ({
		productId,
		variantId,
		quantity,
	}));
	const discountFingerprint = JSON.stringify(items);
	const [appliedFingerprint, setAppliedFingerprint] = useState("");
	const validDiscount =
		appliedFingerprint === discountFingerprint && appliedCode === code.trim()
			? discount.data
			: undefined;
	const fingerprint = JSON.stringify({
		items: cart.items.map(({ productId, variantId, quantity }) => ({
			productId,
			variantId,
			quantity,
		})),
		email,
		address,
		appliedCode: validDiscount ? appliedCode : "",
	});
	const previousFingerprint = useRef(fingerprint);
	useEffect(() => {
		if (fingerprint !== previousFingerprint.current) {
			previousFingerprint.current = fingerprint;
			if (isPreparing || paymentInitialized || isResuming) return;
			key.current = undefined;
			setPayment(undefined);
		}
	}, [fingerprint, isPreparing, paymentInitialized, isResuming]);
	const activeCart =
		isPreparing || paymentInitialized ? submittedCart : undefined;
	const displayItems = activeCart?.items ?? cart.items;
	const displayDiscount = activeCart ? activeCart.discount : validDiscount;
	const displaySubtotal = displayItems.reduce(
		(total, item) => total + item.price * item.quantity,
		0,
	);
	const complete = (result: CheckoutResult) => {
		void navigate(
			`/shop/orders/${encodeURIComponent(result.orderId)}/confirmation`,
		);
	};
	useEffect(() => {
		if (!cart.isHydrated) return;
		let cancelled = false;
		const checkoutKey = `${cart.storeKey}:checkout`;
		setIsResuming(true);
		key.current = undefined;
		setPayment(undefined);
		setPaymentInitialized(false);
		setSubmittedCart(undefined);
		setResumeFailed(false);
		setValidationError(undefined);
		const restore = async () => {
			let stored: string | null = null;
			let recordRead = false;
			const stillCurrent = () => {
				if (cancelled) return false;
				try {
					return sessionStorage.getItem(checkoutKey) === stored;
				} catch {
					return false;
				}
			};
			try {
				stored = sessionStorage.getItem(checkoutKey);
				recordRead = true;
				const attempt: CheckoutAttempt | null = stored
					? JSON.parse(stored)
					: null;
				if (!attempt?.key || !attempt.fingerprint) return;
				const original = JSON.parse(attempt.fingerprint);
				const input = checkoutSchema.parse({
					items: original.items,
					email: original.email,
					shippingAddress: original.address,
					discountCode: original.appliedCode || undefined,
					idempotencyKey: attempt.key,
				});
				const token = attempt.orderId
					? sessionStorage.getItem(orderTokenKey(attempt.orderId, endpoint))
					: null;
				let result: CheckoutResult | undefined;
				let order: Order | null;
				if (attempt.orderId && token) {
					order = await verifyOrder(attempt.orderId, token);
				} else {
					const uncertainAttempt = JSON.stringify({
						...attempt,
						uncertain: true,
					});
					sessionStorage.setItem(checkoutKey, uncertainAttempt);
					stored = uncertainAttempt;
					result = await checkout.mutateAsync(input);
					if (!stillCurrent()) return;
					paymentRedirectUrl(result.payment);
					sessionStorage.setItem(
						orderTokenKey(result.orderId, endpoint),
						result.accessToken,
					);
					sessionStorage.setItem(
						`${orderTokenKey(result.orderId, endpoint)}:cart`,
						JSON.stringify(input.items),
					);
					const recoveredAttempt = JSON.stringify({
						...attempt,
						orderId: result.orderId,
						uncertain: true,
					});
					sessionStorage.setItem(checkoutKey, recoveredAttempt);
					stored = recoveredAttempt;
					order = await verifyOrder(result.orderId, result.accessToken);
				}
				if (!stillCurrent()) return;
				if (!order)
					throw new Error(
						"Could not verify your previous order. Please retry before starting another payment.",
					);
				if (order.paymentStatus === "paid") {
					await navigate(
						`/shop/orders/${encodeURIComponent(order.id)}/confirmation`,
					);
					return;
				}
				if (isTerminalOrder(order)) {
					sessionStorage.removeItem(checkoutKey);
					key.current = undefined;
					setPayment(undefined);
					setPaymentInitialized(false);
					setSubmittedCart(undefined);
					return;
				}
				result ??= await checkout.mutateAsync(input);
				if (!stillCurrent()) return;
				paymentRedirectUrl(result.payment);
				key.current = attempt.key;
				setEmail(input.email);
				setAddress(input.shippingAddress);
				setCode(input.discountCode ?? "");
				setAppliedCode(input.discountCode ?? "");
				setAppliedFingerprint(JSON.stringify(input.items));
				setSubmittedCart({
					items: order.lineItems.map((item) => ({
						...item,
						currency: order.currency,
					})),
					discount: input.discountCode
						? {
								code: input.discountCode,
								discount: order.discount,
								subtotal: order.subtotal,
								total: order.total,
								currency: order.currency,
							}
						: undefined,
					fingerprint: JSON.stringify(input.items),
				});
				setPayment(result);
				setPaymentInitialized(true);
				setStep("payment");
			} catch (error) {
				if (!cancelled && (!recordRead || stillCurrent())) {
					setValidationError(
						error instanceof Error ? error : new Error(String(error)),
					);
					setResumeFailed(true);
				}
			} finally {
				if (!cancelled) setIsResuming(false);
			}
		};
		void restore();
		return () => {
			cancelled = true;
		};
	}, [cart.isHydrated, cart.storeKey, resumeVersion]);
	const placeOrder = async () => {
		if (submitting.current || applyingDiscount.current || isResuming) return;
		submitting.current = true;
		setIsPreparing(true);
		setSubmittedCart({
			items: cart.items.map((item) => ({ ...item })),
			discount: validDiscount,
			fingerprint: discountFingerprint,
		});
		let submittedKey: string | undefined;
		const checkoutKey = `${cart.storeKey}:checkout`;
		try {
			setValidationError(undefined);
			const stored = sessionStorage.getItem(checkoutKey);
			let previous: CheckoutAttempt | undefined;
			if (stored) {
				try {
					previous = JSON.parse(stored);
				} catch {
					/* Invalid saved attempts are replaced below. */
				}
			}
			const reusable = await reusableCheckoutAttempt(
				previous,
				fingerprint,
				async (id) => {
					const token =
						sessionStorage.getItem(orderTokenKey(id, endpoint)) ?? "";
					const order = await verifyOrder(id, token);
					if (!order)
						throw new Error(
							"Could not verify your previous order. Please retry before starting another payment.",
						);
					return order;
				},
			);
			if (previous && typeof previous.key === "string" && !reusable) {
				if (sessionStorage.getItem(checkoutKey) !== stored)
					throw new Error(
						"Your checkout changed in another view. Please retry.",
					);
				sessionStorage.removeItem(checkoutKey);
				key.current = undefined;
				previous = undefined;
				setPaymentInitialized(false);
			}
			if (!key.current && reusable?.key) key.current = reusable.key;
			key.current ??= crypto.randomUUID();
			const idempotencyKey = key.current;
			sessionStorage.setItem(
				checkoutKey,
				JSON.stringify({
					...(reusable?.key === idempotencyKey ? reusable : {}),
					fingerprint,
					key: idempotencyKey,
				}),
			);
			submittedKey = idempotencyKey;
			const result = await checkout.mutateAsync({
				items,
				email,
				shippingAddress: address,
				discountCode: validDiscount ? appliedCode : undefined,
				idempotencyKey,
			});
			const redirectUrl = paymentRedirectUrl(result.payment);
			try {
				const attempt = JSON.parse(
					sessionStorage.getItem(checkoutKey) ?? "null",
				);
				if (attempt?.key === idempotencyKey) {
					sessionStorage.setItem(
						checkoutKey,
						JSON.stringify({ ...attempt, orderId: result.orderId }),
					);
				}
				sessionStorage.setItem(
					orderTokenKey(result.orderId, endpoint),
					result.accessToken,
				);
				sessionStorage.setItem(
					`${orderTokenKey(result.orderId, endpoint)}:cart`,
					JSON.stringify(items),
				);
			} catch {
				throw new Error(
					"Allow session storage to keep your secure order access, then retry payment.",
				);
			}
			setPayment(result);
			setPaymentInitialized(true);
			if (redirectUrl) window.location.assign(redirectUrl);
			else if (!result.payment.clientSecret) complete(result);
		} catch (cause) {
			if (submittedKey) {
				try {
					const attempt: CheckoutAttempt | undefined = JSON.parse(
						sessionStorage.getItem(checkoutKey) ?? "null",
					);
					const code =
						cause instanceof Error && "code" in cause ? cause.code : undefined;
					if (canDiscardCheckoutAttempt(attempt, submittedKey, code)) {
						sessionStorage.removeItem(checkoutKey);
						setSubmittedCart(undefined);
						if (key.current === submittedKey) key.current = undefined;
					} else if (attempt?.key === submittedKey) {
						sessionStorage.setItem(
							checkoutKey,
							JSON.stringify({ ...attempt, uncertain: true }),
						);
					}
				} catch {
					/* Preserve an uncertain attempt when storage cleanup fails. */
				}
			}
			setValidationError(
				cause instanceof Error ? cause : new Error(String(cause)),
			);
		} finally {
			submitting.current = false;
			setIsPreparing(false);
		}
	};
	return (
		<Storefront>
			{!cart.isHydrated ? (
				<p role="status">Loading cart…</p>
			) : isResuming ? (
				<p role="status">Restoring checkout…</p>
			) : resumeFailed ? (
				<section className="space-y-4 py-8">
					<h1 className="text-2xl font-semibold">
						Resume your previous payment
					</h1>
					<ErrorMessage error={validationError} />
					<p className="text-sm text-muted-foreground">
						Use the same account and browser that started this payment. If the
						problem continues, contact the shop before starting another order.
					</p>
					<Button onClick={() => setResumeVersion((version) => version + 1)}>
						Retry previous payment
					</Button>
				</section>
			) : displayItems.length ? (
				<>
					<h1 className="text-3xl font-semibold tracking-tight">Checkout</h1>
					<ol
						aria-label="Checkout progress"
						className="my-7 flex flex-wrap gap-6 text-sm"
					>
						<li>Cart</li>
						<li
							aria-current={step === "shipping" ? "step" : undefined}
							className={
								step === "shipping" ? "font-semibold" : "text-muted-foreground"
							}
						>
							Shipping
						</li>
						<li
							aria-current={step === "payment" ? "step" : undefined}
							className={
								step === "payment" ? "font-semibold" : "text-muted-foreground"
							}
						>
							Payment
						</li>
						<li className="text-muted-foreground">Confirmation</li>
					</ol>
					<div className="grid items-start gap-10 md:grid-cols-[minmax(0,1fr)_20rem]">
						<section>
							{step === "shipping" ? (
								<form
									className="space-y-5"
									onSubmit={(event) => {
										event.preventDefault();
										const parsed = z
											.object({
												email: z.email(),
												address: shippingAddressSchema,
											})
											.safeParse({ email, address });
										if (!parsed.success) {
											setValidationError(
												new Error(
													parsed.error.issues
														.map(
															(issue) =>
																`${issue.path.join(" ")}: ${issue.message}`,
														)
														.join("; "),
												),
											);
											return;
										}
										setAddress(parsed.data.address);
										setEmail(parsed.data.email);
										setValidationError(undefined);
										setStep("payment");
									}}
								>
									<h2 className="text-xl font-medium">Shipping address</h2>
									<label className="block text-sm">
										Email
										<Input
											className="mt-2"
											type="email"
											autoComplete="email"
											required
											value={email}
											onChange={(event) => setEmail(event.target.value)}
										/>
									</label>
									{addressFields.map(([name, label, autoComplete]) => (
										<label className="block text-sm" key={name}>
											{label}
											<Input
												className="mt-2"
												autoComplete={autoComplete}
												required={name !== "line2" && name !== "region"}
												maxLength={name === "country" ? 2 : 200}
												placeholder={name === "country" ? "US" : undefined}
												value={address[name] ?? ""}
												onChange={(event) =>
													setAddress((current) => ({
														...current,
														[name]:
															name === "country"
																? event.target.value.toUpperCase()
																: event.target.value,
													}))
												}
											/>
										</label>
									))}
									<ErrorMessage error={validationError} />
									<Button type="submit" className="h-11">
										Continue to payment
									</Button>
								</form>
							) : (
								<div className="space-y-6">
									<div className="flex items-start justify-between gap-4">
										<div>
											<h2 className="text-xl font-medium">Payment</h2>
											<p className="mt-2 text-sm text-muted-foreground">
												{email}
											</p>
											<p className="mt-1 text-sm text-muted-foreground">
												{address.line1}, {address.city}, {address.postalCode}
											</p>
										</div>
										<Button
											variant="ghost"
											onClick={() => setStep("shipping")}
											disabled={
												paymentInitialized || checkout.isPending || isPreparing
											}
										>
											Edit shipping
										</Button>
									</div>
									<p className="text-sm leading-6 text-muted-foreground">
										Your payment provider will confirm the final total and
										complete payment securely.
									</p>
									<ErrorMessage error={validationError ?? checkout.error} />
									{payment?.payment.redirectUrl ? (
										<Button asChild className="h-11 w-full">
											<a href={payment.payment.redirectUrl}>
												Resume secure payment
											</a>
										</Button>
									) : payment?.payment.clientSecret ? (
										PaymentForm ? (
											<PaymentForm
												clientSecret={payment.payment.clientSecret}
												orderId={payment.orderId}
												onComplete={() => complete(payment)}
											/>
										) : (
											<p role="alert" className="text-sm text-destructive">
												This payment provider requires a payment form. Configure
												the Ecommerce PaymentForm override to continue.
											</p>
										)
									) : (
										<Button
											className="h-11 w-full"
											disabled={
												checkout.isPending || isPreparing || discount.isPending
											}
											onClick={() => void placeOrder()}
										>
											{checkout.isPending || isPreparing
												? "Preparing payment…"
												: "Continue to secure payment"}
										</Button>
									)}
								</div>
							)}
						</section>
						<aside className="rounded-lg bg-muted/40 p-6">
							<h2 className="text-lg font-medium">Order summary</h2>
							{activeCart && activeCart.fingerprint !== discountFingerprint ? (
								<p role="status" className="mt-3 text-sm text-muted-foreground">
									This payment is for the items shown below. Cart changes apply
									to a future order.
								</p>
							) : null}
							<ul className="mt-4 divide-y">
								{displayItems.map((item) => (
									<li
										key={`${item.productId}:${item.variantId ?? ""}`}
										className="flex justify-between gap-3 py-3 text-sm"
									>
										<span>
											{item.name}
											{item.variantName ? ` (${item.variantName})` : ""} ×{" "}
											{item.quantity}
										</span>
										<span className="shrink-0 tabular-nums">
											{formatMoney(item.price * item.quantity, item.currency)}
										</span>
									</li>
								))}
							</ul>
							<form
								className="mt-5 space-y-2"
								onSubmit={async (event) => {
									event.preventDefault();
									if (
										submitting.current ||
										applyingDiscount.current ||
										paymentInitialized
									)
										return;
									applyingDiscount.current = true;
									try {
										await discount.mutateAsync({ code, items });
										setAppliedCode(code.trim());
										setAppliedFingerprint(discountFingerprint);
									} catch {
										setAppliedCode("");
									} finally {
										applyingDiscount.current = false;
									}
								}}
							>
								<label className="text-sm" htmlFor="discount-code">
									Discount code
								</label>
								<div className="flex gap-2">
									<Input
										id="discount-code"
										disabled={discountLocked}
										value={code}
										onChange={(event) => setCode(event.target.value)}
									/>
									<Button
										variant="outline"
										type="submit"
										disabled={!code.trim() || discountLocked}
									>
										{discount.isPending ? "Checking…" : "Apply"}
									</Button>
								</div>
								<ErrorMessage error={discount.error} />
							</form>
							{displayDiscount ? (
								<p role="status" className="mt-4 flex justify-between text-sm">
									<span>{displayDiscount.code} applied</span>
									<span>
										−
										{formatMoney(
											displayDiscount.discount,
											displayDiscount.currency,
										)}
									</span>
								</p>
							) : null}
							<p className="mt-6 flex justify-between border-t pt-4 font-medium">
								<span>{displayDiscount ? "After discount" : "Subtotal"}</span>
								<span className="tabular-nums">
									{formatMoney(
										displayDiscount?.total ?? displaySubtotal,
										displayDiscount?.currency ??
											displayItems[0]?.currency ??
											"USD",
									)}
								</span>
							</p>
							<p className="mt-3 text-xs leading-5 text-muted-foreground">
								Shipping and final prices are confirmed by the server before
								payment.
							</p>
						</aside>
					</div>
				</>
			) : (
				<EmptyCart />
			)}
		</Storefront>
	);
}

"use client";
import { useEffect, useState } from "react";
import { usePluginSiteNavigation } from "@btst/stack/context";
import { Button } from "@/components/ui/button";
import { useEcommerceEndpoint } from "@btst/plugin-ecommerce/client/hooks";
import { useOrderConfirmation } from "@btst/plugin-ecommerce/client/hooks";
import { useCart } from "@btst/plugin-ecommerce/client/hooks";
import { ECOMMERCE_PLUGIN_ID } from "../../constants";
import { ErrorMessage, Storefront, formatMoney } from "../storefront";
import { OrderSummary } from "../order-summary";
import { isTerminalOrder } from "../../checkout-attempt";
import { orderTokenKey } from "../../order-access";

export function OrderConfirmationPage({ id }: { id: string }) {
	const [token, setToken] = useState("");
	const [loaded, setLoaded] = useState(false);
	const cart = useCart();
	const endpoint = useEcommerceEndpoint();
	useEffect(() => {
		try {
			setToken(sessionStorage.getItem(orderTokenKey(id, endpoint)) ?? "");
		} catch {
			setToken("");
		}
		setLoaded(true);
	}, [id, endpoint]);
	const order = useOrderConfirmation(id, token);
	const { Link, resolve } = usePluginSiteNavigation(ECOMMERCE_PLUGIN_ID);
	useEffect(() => {
		if (
			!order.data ||
			order.data.paymentStatus !== "pending" ||
			order.data.status === "cancelled"
		)
			return;
		const timer = window.setInterval(() => {
			if (document.visibilityState === "visible") void order.refetch();
		}, 2500);
		return () => window.clearInterval(timer);
	}, [order.data?.paymentStatus, order.data?.status, order.refetch]);
	useEffect(() => {
		if (!order.data || !isTerminalOrder(order.data)) return;
		try {
			const checkoutKey = `${cart.storeKey}:checkout`;
			const attempt = JSON.parse(sessionStorage.getItem(checkoutKey) ?? "null");
			if (attempt?.orderId === id) sessionStorage.removeItem(checkoutKey);
		} catch {
			/* Storage cleanup must not hide a verified order. */
		}
	}, [id, cart.storeKey, order.data?.paymentStatus, order.data?.status]);
	useEffect(() => {
		if (!order.data || order.data.paymentStatus !== "paid") return;
		try {
			const snapshot = sessionStorage.getItem(
				`${orderTokenKey(id, endpoint)}:cart`,
			);
			if (
				snapshot ===
				JSON.stringify(
					cart.items.map(({ productId, variantId, quantity }) => ({
						productId,
						variantId,
						quantity,
					})),
				)
			) {
				cart.clear();
				sessionStorage.removeItem(`${orderTokenKey(id, endpoint)}:cart`);
			}
		} catch {
			/* Cart cleanup is optional when browser storage is unavailable. */
		}
	}, [id, endpoint, order.data?.paymentStatus, cart]);
	const paid = order.data?.paymentStatus === "paid";
	return (
		<Storefront>
			{loaded && !token ? (
				<section className="py-12">
					<h1 className="text-2xl font-semibold">Order access required</h1>
					<p className="mt-3 text-muted-foreground">
						Open this page in the browser where you checked out, or contact the
						shop with your order number.
					</p>
				</section>
			) : (
				<>
					<header className="mb-8">
						<p className="mb-3 text-sm text-muted-foreground">Order {id}</p>
						<h1 className="text-3xl font-semibold tracking-tight">
							{paid
								? "Payment confirmed"
								: order.data?.status === "cancelled"
									? "Order cancelled"
									: order.data?.paymentStatus === "failed"
										? "Payment was not completed"
										: order.data?.paymentStatus === "refunded"
											? "Payment refunded"
											: "Waiting for payment confirmation"}
						</h1>
						<p className="mt-3 max-w-xl text-muted-foreground">
							{paid
								? `Your payment of ${formatMoney(order.data?.total ?? 0, order.data?.currency ?? "USD")} is confirmed.`
								: order.data?.status === "cancelled"
									? "This order was cancelled. Your cart is available if you would like to start again."
									: order.data?.paymentStatus === "failed"
										? "Your payment did not complete. Return to checkout to try again."
										: order.data?.paymentStatus === "refunded"
											? "Your payment provider has reported a refund for this order."
											: "Your order is confirmed only after the payment provider sends a verified payment notification."}
						</p>
					</header>
					<ErrorMessage error={order.error} />
					{order.isFetching && !order.data ? (
						<p role="status">Loading order…</p>
					) : null}
					{order.data ? <OrderSummary order={order.data} /> : null}
					{!paid ? (
						<Button
							variant="outline"
							className="mt-6"
							disabled={order.isFetching}
							onClick={() => void order.refetch()}
						>
							Refresh payment status
						</Button>
					) : null}
				</>
			)}
			<Link
				className="mt-8 inline-block text-sm underline underline-offset-4"
				href={resolve("/shop").href}
			>
				Continue shopping
			</Link>
		</Storefront>
	);
}

"use client";
import { useState } from "react";
import { PermissionAccess, usePluginSiteNavigation } from "@btst/stack/context";
import { Button } from "@/components/ui/button";
import { ecommercePermissions } from "../../../permissions";
import type { OrderStatus } from "../../../types";
import { ECOMMERCE_PLUGIN_ID } from "../../constants";
import { useOrder, useUpdateOrderStatus } from "@btst/plugin-ecommerce/client/hooks";
import { ErrorMessage, Storefront } from "../storefront";
import { OrderSummary } from "../order-summary";

const nextStatuses: Record<OrderStatus, OrderStatus[]> = {
	pending: ["cancelled"],
	paid: ["fulfilling", "cancelled"],
	fulfilling: ["fulfilled", "cancelled"],
	fulfilled: [],
	cancelled: [],
};
export function OrderDetailPage({ id }: { id: string }) {
	const order = useOrder(id);
	const update = useUpdateOrderStatus();
	const [status, setStatus] = useState<OrderStatus | "">("");
	const { Link, resolve } = usePluginSiteNavigation(ECOMMERCE_PLUGIN_ID);
	return (
		<Storefront>
			<Link
				href={resolve("/shop/admin/orders").href}
				className="mb-6 inline-block text-sm underline underline-offset-4"
			>
				All orders
			</Link>
			<h1 className="mb-8 break-all text-2xl font-semibold tracking-tight">
				Order {id}
			</h1>
			<ErrorMessage error={order.error ?? update.error} />
			{order.isPending ? <p role="status">Loading order…</p> : null}
			{order.data ? (
				<>
					<OrderSummary order={order.data} />
					{nextStatuses[order.data.status].length ? (
						<PermissionAccess
							permission={ecommercePermissions.order.update({ id })}
						>
							<form
								className="mt-8 flex flex-wrap items-end gap-3 border-t pt-6"
								onSubmit={async (event) => {
									event.preventDefault();
									if (!status) return;
									try {
										await update.mutateAsync({ id, status });
										setStatus("");
										await order.refetch();
									} catch {
										/* The mutation error is shown above. */
									}
								}}
							>
								<label className="text-sm">
									Update order status
									<select
										className="mt-2 block h-10 rounded-md border bg-background px-3"
										value={status}
										onChange={(event) =>
											setStatus(event.target.value as OrderStatus | "")
										}
									>
										<option value="">Choose status</option>
										{nextStatuses[order.data.status].map((value) => (
											<option key={value} value={value}>
												{value}
											</option>
										))}
									</select>
								</label>
								<Button type="submit" disabled={!status || update.isPending}>
									{update.isPending ? "Saving…" : "Save status"}
								</Button>
							</form>
						</PermissionAccess>
					) : null}
				</>
			) : null}
		</Storefront>
	);
}

"use client";
import { useState } from "react";
import { useIdentity, usePluginSiteNavigation } from "@btst/stack/context";
import { Button } from "@/components/ui/button";
import type { OrderStatus, OrdersPage } from "../../../types";
import { useMyOrders, useOrders } from "@btst/plugin-ecommerce/client/hooks";
import { ECOMMERCE_PLUGIN_ID } from "../../constants";
import { ErrorMessage, Storefront, formatMoney } from "../storefront";

function OrdersTable({
	data,
	admin = false,
}: {
	data?: OrdersPage;
	admin?: boolean;
}) {
	const { Link, resolve } = usePluginSiteNavigation(ECOMMERCE_PLUGIN_ID);
	if (!data?.items.length)
		return <p className="py-12 text-muted-foreground">No orders yet.</p>;
	return (
		<div className="overflow-x-auto">
			<table className="w-full text-left text-sm">
				<caption className="sr-only">
					{admin ? "All customer orders" : "Your orders"}
				</caption>
				<thead className="border-b text-muted-foreground">
					<tr>
						<th scope="col" className="py-3 pr-4 font-medium">
							Order
						</th>
						<th scope="col" className="py-3 pr-4 font-medium">
							Date
						</th>
						{admin ? (
