"use client";
import { useState } from "react";
import { usePluginSiteNavigation } from "@btst/stack/context";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { useSuspenseProduct } from "@btst/plugin-ecommerce/client/hooks";
import { useCart } from "@btst/plugin-ecommerce/client/hooks";
import { ECOMMERCE_PLUGIN_ID } from "../../constants";
import { ProductImage } from "../product-image";
import { ErrorMessage, Storefront, formatMoney } from "../storefront";

export function ProductDetailPage({ slug }: { slug: string }) {
	const { data: product } = useSuspenseProduct(slug);
	const [selectedImage, setSelectedImage] = useState(0);
	const [variantId, setVariantId] = useState(product.variants[0]?.id ?? "");
	const [quantity, setQuantity] = useState(1);
	const [added, setAdded] = useState(false);
	const [error, setError] = useState<Error>();
	const cart = useCart();
	const variant = product.variants.find((entry) => entry.id === variantId);
	const stock = variant?.stock ?? product.stock;
	const price = variant?.price ?? product.price;
	const { Link, resolve } = usePluginSiteNavigation(ECOMMERCE_PLUGIN_ID);
	return (
		<Storefront>
			<Link
				className="mb-6 inline-block text-sm text-muted-foreground underline underline-offset-4"
				href={resolve("/shop").href}
			>
				All products
			</Link>
			<div className="grid items-start gap-8 md:grid-cols-[minmax(0,1.2fr)_minmax(0,1fr)] lg:gap-14">
				<div>
					<div className="aspect-square overflow-hidden rounded-xl bg-muted">
						<ProductImage
							image={product.images[selectedImage]}
							alt={product.name}
							priority
						/>
					</div>
					{product.images.length > 1 ? (
						<div className="mt-3 flex gap-3 overflow-auto">
							{product.images.map((image, index) => (
								<button
									key={`${image}:${index}`}
									type="button"
									aria-label={`View image ${index + 1}`}
									aria-pressed={selectedImage === index}
									className={`h-20 w-20 shrink-0 overflow-hidden rounded-md border-2 ${selectedImage === index ? "border-primary" : "border-transparent"}`}
									onClick={() => setSelectedImage(index)}
								>
									<ProductImage
										image={image}
										alt={`${product.name}, image ${index + 1}`}
									/>
								</button>
							))}
						</div>
					) : null}
				</div>
				<section className="md:sticky md:top-6">
					{product.category ? (
						<p className="mb-3 text-sm text-muted-foreground">
							{product.category}
						</p>
					) : null}
					<h1 className="text-3xl font-semibold tracking-tight">
						{product.name}
					</h1>
					<p className="mt-5 text-2xl font-medium tabular-nums">
						{formatMoney(price, product.currency)}
					</p>
					<p className="mt-2 text-sm text-muted-foreground">
						{stock > 0 ? `${stock} in stock` : "Out of stock"}
					</p>
					<form
						className="mt-8 space-y-5"
						onSubmit={(event) => {
							event.preventDefault();
							try {
								cart.addItem({
									productId: product.id,
									variantId: variant?.id,
									name: product.name,
									variantName: variant?.name,
									price,
									currency: product.currency,
									image: product.images[0],
									quantity,
								});
								setError(undefined);
								setAdded(true);
							} catch (cause) {
								setError(
									cause instanceof Error ? cause : new Error(String(cause)),
								);
							}
						}}
					>
						{product.variants.length ? (
							<label className="block text-sm font-medium">
								Variant
								<select
									className="mt-2 h-11 w-full rounded-md border bg-background px-3 font-normal"
									value={variantId}
									onChange={(event) => {
										setVariantId(event.target.value);
										setAdded(false);
										setQuantity(1);
									}}
								>
									{product.variants.map((entry) => (
										<option key={entry.id} value={entry.id}>
											{entry.name}
											{entry.stock === 0 ? " — out of stock" : ""}
										</option>
									))}
								</select>
							</label>
						) : null}
						<label className="block text-sm font-medium">
							Quantity
							<Input
								className="mt-2 w-24"
								type="number"
								min={1}
								max={Math.min(stock, 99)}
								value={quantity}
								onChange={(event) => {
									setQuantity(Number(event.target.value));
									setAdded(false);
								}}
							/>
						</label>
						<ErrorMessage error={error} />
						<Button
							className="h-11 w-full"
							type="submit"
							disabled={
								!cart.isHydrated ||
								stock === 0 ||
								quantity < 1 ||
								quantity > Math.min(stock, 99)
							}
						>
							Add to cart
						</Button>
						{added ? (
							<p role="status" className="text-sm">
								Added to your cart.{" "}
								<Link
									className="underline underline-offset-4"
									href={resolve("/shop/cart").href}
								>
									Review cart
								</Link>
							</p>
						) : null}
					</form>
					{product.description ? (
						<div className="mt-10 border-t pt-6">
							<h2 className="mb-3 text-lg font-medium">Details</h2>
							<p className="whitespace-pre-wrap text-sm leading-7 text-muted-foreground">
								{product.description}
							</p>
						</div>
					) : null}
				</section>
			</div>
		</Storefront>
	);
}

"use client";
import { useDeferredValue, useState } from "react";
import { usePluginSiteNavigation, useStack } from "@btst/stack/context";
import { Input } from "@/components/ui/input";
import { Button } from "@/components/ui/button";
import { ECOMMERCE_PLUGIN_ID } from "../../constants";
import { useProducts } from "@btst/plugin-ecommerce/client/hooks";
import { ProductImage } from "../product-image";
import {
	ErrorMessage,
	Storefront,
	formatMoney,
	currencyScale,
} from "../storefront";

export function ProductListPage() {
	const { plugins } = useStack();
	const configuredCurrency = plugins?.[ECOMMERCE_PLUGIN_ID]?.config?.currency;
	const priceScale = currencyScale(
		typeof configuredCurrency === "string" ? configuredCurrency : "USD",
	);
	const [search, setSearch] = useState("");
	const [category, setCategory] = useState("");
	const [collection, setCollection] = useState("");
	const [minPrice, setMinPrice] = useState("");
	const [maxPrice, setMaxPrice] = useState("");
	const [inStock, setInStock] = useState(false);
	const [offset, setOffset] = useState(0);
	const filters = {
		search: useDeferredValue(search) || undefined,
		category: category || undefined,
		collection: collection || undefined,
		minPrice: minPrice ? Math.round(Number(minPrice) * priceScale) : undefined,
		maxPrice: maxPrice ? Math.round(Number(maxPrice) * priceScale) : undefined,
		inStock: inStock || undefined,
		limit: 24,
		offset,
	};
	const products = useProducts(filters);
	const { Link, resolve } = usePluginSiteNavigation(ECOMMERCE_PLUGIN_ID);
	const resetPage = () => setOffset(0);
	return (
		<Storefront>
			<header className="mb-8 flex items-end justify-between gap-4">
				<div>
					<h1 className="text-3xl font-semibold tracking-tight">Products</h1>
					<p className="mt-2 text-muted-foreground">
						Browse the catalog and choose what works for you.
					</p>
				</div>
				{products.data ? (
					<p className="text-sm text-muted-foreground">
						{products.data.total}{" "}
						{products.data.total === 1 ? "product" : "products"}
					</p>
				) : null}
			</header>
			<form
				aria-label="Filter products"
				className="mb-8 grid gap-4 rounded-lg bg-muted/40 p-4 sm:grid-cols-2 lg:grid-cols-6"
				onSubmit={(event) => event.preventDefault()}
			>
				<label className="text-sm">
					Search
					<Input
						type="search"
						value={search}
						onChange={(event) => {
							setSearch(event.target.value);
							resetPage();
						}}
						className="mt-1"
						placeholder="Product name"
					/>
				</label>
				<label className="text-sm">
					Category
					<select
						className="mt-1 h-9 w-full rounded-md border bg-background px-2"
						value={category}
						onChange={(event) => {
							setCategory(event.target.value);
							resetPage();
						}}
					>
						<option value="">All categories</option>
						{products.data?.categories.map((value) => (
							<option key={value}>{value}</option>
						))}
					</select>
				</label>
				<label className="text-sm">
					Collection
					<select
						className="mt-1 h-9 w-full rounded-md border bg-background px-2"
						value={collection}
						onChange={(event) => {
							setCollection(event.target.value);
							resetPage();
						}}
					>
						<option value="">All collections</option>
						{products.data?.collections.map((value) => (
							<option key={value}>{value}</option>
						))}
					</select>
				</label>
				<label className="text-sm">
					Minimum price
					<Input
						className="mt-1"
						type="number"
						min={0}
						step={1 / priceScale}
						value={minPrice}
						onChange={(event) => {
							setMinPrice(event.target.value);
							resetPage();
						}}
					/>
				</label>
				<label className="text-sm">
					Maximum price
					<Input
						className="mt-1"
						type="number"
						min={0}
						step={1 / priceScale}
						value={maxPrice}
						onChange={(event) => {
							setMaxPrice(event.target.value);
							resetPage();
						}}
					/>
				</label>
				<label className="flex items-center gap-2 self-end py-2 text-sm">
					<input
						type="checkbox"
						checked={inStock}
						onChange={(event) => {
							setInStock(event.target.checked);
							resetPage();
						}}
					/>
					In stock only
				</label>
			</form>
			<ErrorMessage error={products.error} />
			{products.isPending ? (
				<p role="status" className="py-12 text-muted-foreground">
					Loading products…
				</p>
			) : null}
			{products.data?.items.length === 0 ? (
				<div className="py-16 text-center">
					<h2 className="text-xl font-medium">
						No products match your filters
					</h2>
					<p className="mt-2 text-muted-foreground">
						Try another category or a wider price range.
					</p>
				</div>
			) : null}
			<div className="grid grid-cols-1 gap-x-6 gap-y-10 sm:grid-cols-2 lg:grid-cols-3">
				{products.data?.items.map((product) => {
					const available = product.variants.length
						? product.variants.some((variant) => variant.stock > 0)
						: product.stock > 0;
					return (
						<Link
							key={product.id}
							href={
								resolve(`/shop/products/${encodeURIComponent(product.slug)}`)
									.href
							}
							className="group block rounded-lg focus-visible:outline-2 focus-visible:outline-offset-4 focus-visible:outline-ring"
						>
							<div className="aspect-square overflow-hidden rounded-lg bg-muted">
								<ProductImage image={product.images[0]} alt={product.name} />
							</div>
							<div className="mt-4 flex items-start justify-between gap-4">
								<div>
									<h2 className="font-medium group-hover:underline">
										{product.name}
									</h2>
									{product.category ? (
										<p className="mt-1 text-sm text-muted-foreground">
											{product.category}
										</p>
									) : null}
								</div>
								<span className="shrink-0 font-medium tabular-nums">
									{product.variants.length ? "From " : ""}
									{formatMoney(
										product.variants.length
											? Math.min(
													...product.variants.map(
														(variant) => variant.price ?? product.price,
													),
												)
											: product.price,
										product.currency,
									)}
								</span>
							</div>
							{!available ? (
								<p className="mt-2 text-sm text-muted-foreground">
									Out of stock
								</p>
							) : null}
						</Link>
					);
				})}
			</div>
			{products.data && products.data.total > 24 ? (
				<nav
					aria-label="Product pages"
					className="mt-10 flex items-center justify-between"
				>
					<Button
						variant="outline"
						disabled={offset === 0}
						onClick={() => setOffset(Math.max(0, offset - 24))}
					>
						Previous
					</Button>
					<span className="text-sm">Page {Math.floor(offset / 24) + 1}</span>
					<Button
						variant="outline"
						disabled={offset + 24 >= products.data.total}
						onClick={() => setOffset(offset + 24)}
					>
						Next
					</Button>
				</nav>
			) : null}
		</Storefront>
	);
}

"use client";
import { lazy } from "react";
import type { FallbackProps } from "react-error-boundary";
import { ComposedRoute } from "@btst/stack/client/components";
import { ecommercePermissions } from "../../../permissions";

const ProductList = lazy(() =>
	import("./product-list-page.internal").then((module) => ({
		default: module.ProductListPage,
	})),
);
const ProductDetail = lazy(() =>
	import("./product-detail-page.internal").then((module) => ({
		default: module.ProductDetailPage,
	})),
);
const Cart = lazy(() =>
	import("./cart-page.internal").then((module) => ({
		default: module.CartPage,
	})),
);
const Checkout = lazy(() =>
	import("./checkout-page.internal").then((module) => ({
		default: module.CheckoutPage,
	})),
);
const Confirmation = lazy(() =>
	import("./order-confirmation-page.internal").then((module) => ({
		default: module.OrderConfirmationPage,
	})),
);
const Orders = lazy(() =>
	import("./orders-admin-page.internal").then((module) => ({
		default: module.OrdersAdminPage,
	})),
);
const OrderDetail = lazy(() =>
	import("./order-detail-page.internal").then((module) => ({
		default: module.OrderDetailPage,
	})),
);
const MyOrders = lazy(() =>
	import("./orders-admin-page.internal").then((module) => ({
		default: module.MyOrdersPage,
	})),
);
function Loading() {
	return (
		<p className="p-8 text-sm text-muted-foreground" role="status">
			Loading shop…
		</p>
	);
}
function RouteError({ error }: FallbackProps) {
	return (
		<div className="mx-auto max-w-3xl p-8">
			<h1 className="text-xl font-semibold">Unable to load this page</h1>
			<p className="mt-3 text-sm text-destructive" role="alert">
				{error instanceof Error ? error.message : "Please try again."}
			</p>
		</div>
	);
}
function NotFound() {
	return <p className="p-8">This product or order could not be found.</p>;
}
const common = {
	ErrorComponent: RouteError,
	LoadingComponent: Loading,
	NotFoundComponent: NotFound,
	onError: (error: Error) =>
		console.error("[btst/ecommerce] Page error", error),
};
export function ProductListPageComponent() {
	return <ComposedRoute {...common} path="/shop" PageComponent={ProductList} />;
}
